<?php $title='Explore Events';require dirname(__DIR__).'/layouts/header.php';?><div class="page-heading"><div class="eyebrow">DISCOVER SOMETHING NEW</div><h1>Explore events</h1><p>Temukan pengalaman berikutnya.</p></div><form class="filter-bar" method="get"><input name="q" placeholder="Search event or city..." value="<?=e($q)?>"><select name="category"><option value="0">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn">Search</button></form><div class="event-grid"><?php foreach($events as $ev):?><a class="event-card" href="<?=e(url('events/'.$ev['slug']))?>"><div class="event-art"><span><?=e($ev['category_name']??'EVENT')?></span><b><?=e(strtoupper(substr($ev['title'],0,2)))?></b></div><div class="event-info"><div class="muted"><?=e(date('d M Y · H:i',strtotime($ev['start_date'])))?> · <?=e($ev['city'])?></div><h3><?=e($ev['title'])?></h3><div class="muted">By <?=e($ev['organizer_name'])?></div></div></a><?php endforeach;?><?php if(!$events):?><div class="empty">Belum ada event yang cocok. Coba kata kunci lain.</div><?php endif;?></div><?php require dirname(__DIR__).'/layouts/footer.php';?>